package life.milo.companion;
import android.app.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.os.Build;
import android.speech.RecognizerIntent;
import android.speech.tts.TextToSpeech;
import android.widget.*;
import com.google.firebase.auth.*;
import com.google.firebase.firestore.*;
import com.google.firebase.messaging.FirebaseMessaging;
import org.json.*;
import java.util.*;

/** Verified invitations and exact messages; received text is never executed or sent to AI. */
class PeopleScreen {
    final MainActivity a;
    ListenerRegistration contactsListener,inboxListener;
    LinearLayout contacts,inbox;
    TextView feedback;
    Switch notificationSwitch;
    EditText dictationTarget;
    boolean closed;
    int notificationRequest;
    final Map<String,DocumentSnapshot> people=new HashMap<>();
    PeopleScreen(MainActivity activity){a=activity;}
    boolean live(){return !closed&&!a.destroyed&&"People".equals(a.tab);}
    void close(){closed=true;notificationRequest++;if(a.speech!=null)a.speech.stop();if(contactsListener!=null)contactsListener.remove();if(inboxListener!=null)inboxListener.remove();dictationTarget=null;}
    void say(String message){if(live()&&feedback!=null)feedback.setText(message);}
    Button action(LinearLayout parent,String label,Runnable click){Button b=a.button(label,false);parent.addView(b);b.setOnClickListener(v->click.run());return b;}
    LinearLayout form(){LinearLayout p=new LinearLayout(a);p.setOrientation(LinearLayout.VERTICAL);p.setPadding(a.dp(20),a.dp(8),a.dp(20),a.dp(12));return p;}
    void refresh(){if(live())a.show("People");}
    void show(){
        LinearLayout page=a.scrollPage();page.addView(a.text("Your people",26));page.addView(a.text("A small circle for family and friends. Send a message, ask a question, and let them reply in their own time.",14));feedback=a.text("",13);page.addView(feedback);
        action(page,"Add a person",this::addDraft);
        showDrafts(page);
        if(!PeopleClient.ready(a)){page.addView(a.text("People messaging needs activation",20));page.addView(a.text("You can save names on this phone now. Invitations and cross-phone messages will become available after the Milo owner activates the messaging server and rebuilds the app. AI keys do not activate this service.",14));action(page,"See the owner setup guide",()->a.openLink("https://github.com/ArunKammattery23/Milo/blob/main/cloud/README.md"));return;}
        FirebaseUser user=PeopleClient.current();
        if(user==null){showLogin(page);return;}
        page.addView(a.text("Signed in as "+user.getEmail(),13));
        if(!user.isEmailVerified()){
            page.addView(a.text("Verify your email to connect",20));page.addView(a.text("Open the verification email, then return here. Verified email identifies each account; relationship labels are chosen by you.",14));
            action(page,"Send verification email",()->user.sendEmailVerification().addOnSuccessListener(v->say("Verification email requested. Check your inbox.")).addOnFailureListener(e->say("Could not send verification. Try later.")));
            action(page,"I have verified · refresh",()->user.reload().addOnSuccessListener(v->{if(!user.isEmailVerified()){say("Email is not verified yet.");return;}user.getIdToken(true).addOnSuccessListener(t->refresh()).addOnFailureListener(e->say("Sign out and sign in again to refresh verification."));}).addOnFailureListener(e->say("Could not refresh this account.")));
            action(page,"Sign out",this::signOut);return;
        }
        EditText name=a.edit("Your name for messages",false);name.setText(user.getDisplayName()==null?"":user.getDisplayName());page.addView(name);
        Button save=a.button("Save my People name",false);page.addView(save);save.setOnClickListener(v->{String n=name.getText().toString().trim();if(n.isEmpty()||n.length()>40){say("Choose a name up to 40 characters.");return;}save.setEnabled(false);PeopleClient.call("saveProfile",PeopleClient.data("name",n)).addOnSuccessListener(t->{user.updateProfile(new UserProfileChangeRequest.Builder().setDisplayName(n).build());say("Your People name is saved. You can invite someone now.");}).addOnFailureListener(e->say(PeopleClient.error(e))).addOnCompleteListener(t->save.setEnabled(true));});
        page.addView(a.text("Save your name once before sending or accepting invitations.",12));
        action(page,"Invite family or a friend",()->invite("",""));action(page,"Accept an invitation",this::accept);
        Switch notifications=new Switch(a);notificationSwitch=notifications;notifications.setText("Message notifications on this phone");notifications.setChecked(a.prefs.getBoolean("people_notifications",false)&&user.getUid().equals(a.prefs.getString("people_notifications_owner","")));page.addView(notifications);notifications.setOnCheckedChangeListener((b,on)->{if(on){if(a.prefs.getBoolean("people_notifications",false)&&user.getUid().equals(a.prefs.getString("people_notifications_owner","")))return;if(Build.VERSION.SDK_INT>=33&&a.checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED){notifications.setChecked(false);a.requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},92);}else enableNotifications();}else disableNotifications();});
        page.addView(a.text("Notifications contain no message text. Open Milo to read, reply or listen. Delivery can be delayed; this is not an emergency service.",12));
        page.addView(a.text("Connected people",20));contacts=new LinearLayout(a);contacts.setOrientation(LinearLayout.VERTICAL);page.addView(contacts);
        contactsListener=PeopleClient.db().collection("users").document(user.getUid()).collection("contacts").limit(100).addSnapshotListener((result,error)->{if(!live())return;if(error!=null){say("Could not load connections. Check your connection and service setup.");return;}contacts.removeAllViews();people.clear();if(result==null||result.isEmpty()){contacts.addView(a.text("No accepted invitations yet.",14));return;}for(DocumentSnapshot c:result.getDocuments()){people.put(c.getId(),c);Button b=a.button(label(c)+" · "+(Boolean.TRUE.equals(c.getBoolean("active"))?"Connected":Boolean.TRUE.equals(c.getBoolean("blockedByMe"))?"Blocked":"Disconnected"),false);contacts.addView(b);b.setOnClickListener(v->contactOptions(c));}});
        page.addView(a.text("Messages",20));inbox=new LinearLayout(a);inbox.setOrientation(LinearLayout.VERTICAL);page.addView(inbox);
        inboxListener=PeopleClient.db().collection("users").document(user.getUid()).collection("messages").orderBy("createdAt",Query.Direction.DESCENDING).limit(50).addSnapshotListener((result,error)->{if(!live())return;if(error!=null){say("Could not load messages. Try again when connected.");return;}inbox.removeAllViews();if(result==null||result.isEmpty()){inbox.addView(a.text("Messages will appear here.",14));return;}for(DocumentSnapshot m:result.getDocuments()){com.google.firebase.Timestamp expires=m.getTimestamp("expiresAt");if(expires!=null&&expires.toDate().getTime()<=System.currentTimeMillis())continue;boolean mine=user.getUid().equals(m.getString("fromUid"));String peer=mine?m.getString("toUid"):m.getString("fromUid"),who=people.containsKey(peer)?label(people.get(peer)):(mine?"Your connection":m.getString("fromName"));String body=m.getString("text");Button card=a.button((mine?"To ":"From ")+who+"\n"+(body==null?"":body.substring(0,Math.min(90,body.length())))+"\n"+(mine?(m.getTimestamp("readAt")==null?"Stored · awaiting read":"Opened by recipient"):(m.getTimestamp("readAt")==null?"New message":"Opened")),false);card.setGravity(android.view.Gravity.START);inbox.addView(card);card.setOnClickListener(v->openMessage(m));}});
        action(page,"Sign out",this::signOut);
        action(page,"Delete my People account",()->new AlertDialog.Builder(a).setTitle("Delete your People account?").setMessage("This removes your cloud profile, device registration, connections and your message copies. Other people's copies remain until their retention period ends or they delete them. You may need to sign out and sign in again first.").setNegativeButton("Keep account",null).setPositiveButton("Delete account",(d,w)->PeopleClient.call("deleteAccount",PeopleClient.data()).addOnSuccessListener(t->{PeopleClient.signOut(a);refresh();}).addOnFailureListener(e->say(PeopleClient.error(e)))).show());
    }
    void showLogin(LinearLayout page){
        page.addView(a.text("Sign in to connect",20));page.addView(a.text("Messaging uses a verified Milo account. People messages do not use an AI provider. They are stored in Milo's configured cloud service, protected by account access rules; they are not end-to-end encrypted.",13));
        EditText email=a.edit("Email address",false),password=a.edit("Password",false),name=a.edit("Your name",false);email.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_EMAIL_ADDRESS);password.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_PASSWORD);page.addView(email);page.addView(password);page.addView(name);
        Button login=a.button("Sign in",true),signup=a.button("Create an account",false);page.addView(login);page.addView(signup);
        login.setOnClickListener(v->{login.setEnabled(false);FirebaseAuth.getInstance().signInWithEmailAndPassword(email.getText().toString().trim(),password.getText().toString()).addOnSuccessListener(t->{password.setText("");refresh();}).addOnFailureListener(e->say("Sign-in failed. Check your email and password or reset your password.")).addOnCompleteListener(t->login.setEnabled(true));});
        signup.setOnClickListener(v->{String n=name.getText().toString().trim();if(n.isEmpty()||n.length()>40){say("Enter your name, up to 40 characters.");return;}signup.setEnabled(false);FirebaseAuth.getInstance().createUserWithEmailAndPassword(email.getText().toString().trim(),password.getText().toString()).addOnSuccessListener(t->{FirebaseUser u=t.getUser();if(u==null)return;u.updateProfile(new UserProfileChangeRequest.Builder().setDisplayName(n).build()).addOnCompleteListener(update->{u.sendEmailVerification();password.setText("");refresh();});}).addOnFailureListener(e->say("Could not create this account. Check the email, password policy and whether you already have an account.")).addOnCompleteListener(t->signup.setEnabled(true));});
        action(page,"Reset password",()->FirebaseAuth.getInstance().sendPasswordResetEmail(email.getText().toString().trim()).addOnSuccessListener(t->say("If this email can be used for recovery, check its inbox.")).addOnFailureListener(e->say("Could not request password recovery. Check the email address.")));
    }
    JSONArray drafts(){try{return new JSONArray(a.prefs.getString("people_drafts","[]"));}catch(Exception e){return new JSONArray();}}
    void showDrafts(LinearLayout page){JSONArray list=drafts();if(list.length()==0)return;page.addView(a.text("Saved on this phone · not connected",16));for(int i=0;i<list.length();i++){JSONObject p=list.optJSONObject(i);if(p==null)continue;final int index=i;Button b=a.button(p.optString("alias")+"\n"+p.optString("email"),false);page.addView(b);b.setOnClickListener(v->new AlertDialog.Builder(a).setTitle(p.optString("alias")).setItems(new String[]{"Invite this person","Remove saved name"},(d,n)->{if(n==0)invite(p.optString("email"),p.optString("alias"));else{JSONArray all=drafts();all.remove(index);a.prefs.edit().putString("people_drafts",all.toString()).apply();refresh();}}).setNegativeButton("Close",null).show());}}
    void addDraft(){LinearLayout form=form();EditText alias=a.edit("Name / relationship, e.g. Mom",false),email=a.edit("Their email address",false);form.addView(alias);form.addView(email);AlertDialog dialog=new AlertDialog.Builder(a).setTitle("Add a person").setMessage("Save a name locally. They must accept an invitation before Milo can deliver messages.").setView(form).setNegativeButton("Cancel",null).setPositiveButton("Save",null).create();dialog.setOnShowListener(d->dialog.getButton(-1).setOnClickListener(v->{String n=alias.getText().toString().trim(),e=email.getText().toString().trim().toLowerCase(Locale.ROOT);JSONArray list=drafts();if(n.isEmpty()||n.length()>40||e.length()>254||!android.util.Patterns.EMAIL_ADDRESS.matcher(e).matches()||list.length()>=50){say("Use a name up to 40 characters and a valid email. The list holds up to 50 saved names.");return;}try{list.put(new JSONObject().put("alias",n).put("email",e));a.prefs.edit().putString("people_drafts",list.toString()).apply();dialog.dismiss();refresh();}catch(Exception ignored){}}));dialog.show();}
    boolean signedIn(){if(!PeopleClient.ready(a)){say("The owner needs to activate messaging first.");return false;}FirebaseUser u=PeopleClient.current();if(u==null||!u.isEmailVerified()){say("Sign in and verify your email first.");return false;}return true;}
    void invite(String preEmail,String preAlias){if(!signedIn())return;LinearLayout f=form();EditText email=a.edit("Their verified email",false),alias=a.edit("Your name for them, e.g. Son",false);email.setText(preEmail);alias.setText(preAlias);f.addView(email);f.addView(alias);AlertDialog dialog=new AlertDialog.Builder(a).setTitle("Invite someone you know").setMessage("This code works only for this email and expires in 24 hours. You choose whether to share it. Your connected account name and email will be visible to them.").setView(f).setNegativeButton("Cancel",null).setPositiveButton("Create invitation",null).create();dialog.setOnShowListener(d->dialog.getButton(-1).setOnClickListener(v->{dialog.getButton(-1).setEnabled(false);PeopleClient.call("createInvite",PeopleClient.data("email",email.getText().toString().trim(),"alias",alias.getText().toString().trim())).addOnSuccessListener(t->{dialog.dismiss();Map<?,?> data=(Map<?,?>)t.getData();String code=String.valueOf(data.get("code"));if(!live())return;TextView text=a.text("Give this invitation code to "+email.getText()+":\n\n"+code+"\n\nIn Milo: More → People → Accept an invitation.",15);text.setTextIsSelectable(true);text.setPadding(a.dp(20),a.dp(12),a.dp(20),a.dp(12));new AlertDialog.Builder(a).setTitle("Your invitation is ready").setView(text).setPositiveButton("Copy code",(x,w)->{android.content.ClipboardManager clip=(android.content.ClipboardManager)a.getSystemService(Context.CLIPBOARD_SERVICE);clip.setPrimaryClip(ClipData.newPlainText("Milo invitation",code));}).setNegativeButton("Close",null).show();}).addOnFailureListener(e->{say(PeopleClient.error(e));dialog.getButton(-1).setEnabled(true);});}));dialog.show();}
    void accept(){if(!signedIn())return;LinearLayout f=form();EditText code=a.edit("Invitation code",false),alias=a.edit("Your name for them, e.g. Mom",false);f.addView(code);f.addView(alias);AlertDialog dialog=new AlertDialog.Builder(a).setTitle("Accept an invitation").setMessage("Accept only from someone you know. Accepting allows both of you to exchange messages and shows your People name and verified email. You can remove or block the connection anytime.").setView(f).setNegativeButton("Cancel",null).setPositiveButton("Accept and connect",null).create();dialog.setOnShowListener(d->dialog.getButton(-1).setOnClickListener(v->{dialog.getButton(-1).setEnabled(false);PeopleClient.call("acceptInvite",PeopleClient.data("code",code.getText().toString().trim(),"alias",alias.getText().toString().trim())).addOnSuccessListener(t->{dialog.dismiss();refresh();}).addOnFailureListener(e->{say(PeopleClient.error(e));dialog.getButton(-1).setEnabled(true);});}));dialog.show();}
    String label(DocumentSnapshot c){String alias=c.getString("alias");return alias==null?"Your connection":alias;}
    void contactOptions(DocumentSnapshot c){boolean connected=Boolean.TRUE.equals(c.getBoolean("active"));String[] actions=connected?new String[]{"Write a message","Ask where they are","Ask them to come home","Block this person","Remove connection"}:new String[]{Boolean.TRUE.equals(c.getBoolean("blockedByMe"))?"Unblock · invite again to reconnect":"Invite again"};new AlertDialog.Builder(a).setTitle(label(c)+" · "+c.getString("email")).setItems(actions,(d,n)->{if(!connected){if(Boolean.TRUE.equals(c.getBoolean("blockedByMe")))manage(c,"unblock");else invite(c.getString("email"),label(c));return;}if(n<3)compose(c.getId(),label(c),n==1?"Where are you? Please reply when you can.":n==2?"Please come home soon. Let me know when you expect to arrive.":"");else manage(c,n==3?"block":"remove");}).setNegativeButton("Close",null).show();}
    void manage(DocumentSnapshot c,String action){new AlertDialog.Builder(a).setTitle(action.equals("block")?"Block this person?":action.equals("unblock")?"Unblock this person?":"Remove connection?").setMessage("New messages will stop. Existing message copies remain. Reconnecting requires a new invitation after any blocks are removed.").setNegativeButton("Cancel",null).setPositiveButton("Confirm",(d,w)->PeopleClient.call("manageConnection",PeopleClient.data("peerUid",c.getId(),"action",action)).addOnSuccessListener(t->refresh()).addOnFailureListener(e->say(PeopleClient.error(e)))).show();}
    void compose(String peer,String who,String initial){if(!signedIn())return;LinearLayout f=form();EditText body=a.edit("Your message",true);body.setText(initial);body.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(2000)});f.addView(body);action(f,"🎙 Dictate · review first",()->{dictationTarget=body;Intent speech=new Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH).putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL,RecognizerIntent.LANGUAGE_MODEL_FREE_FORM).putExtra(RecognizerIntent.EXTRA_LANGUAGE,a.voiceLocale().toLanguageTag()).putExtra(RecognizerIntent.EXTRA_PROMPT,"Message for "+who+" · review before sending");if(a.speech!=null)a.speech.stop();a.stopService(new Intent(a,BackgroundVoiceService.class));try{a.startActivityForResult(speech,27);}catch(ActivityNotFoundException e){say("Speech recognition is unavailable. Type your message.");}});
        String[] pending={"",""};AlertDialog dialog=new AlertDialog.Builder(a).setTitle("Message to "+who).setView(f).setNegativeButton("Cancel",null).setPositiveButton("Review message",null).create();dialog.setOnDismissListener(d->dictationTarget=null);dialog.setOnShowListener(d->dialog.getButton(-1).setOnClickListener(v->{String value=body.getText().toString().trim();if(value.isEmpty()){body.setError("Write a message first");return;}new AlertDialog.Builder(a).setTitle("Send to "+who+"?").setMessage(value+"\n\nMilo will relay these exact words. Your account name and email identify the sender.").setNegativeButton("Edit",null).setPositiveButton("Send",(x,w)->{if(!pending[1].equals(value)){pending[0]=UUID.randomUUID().toString();pending[1]=value;}dialog.getButton(-1).setEnabled(false);PeopleClient.call("sendMessage",PeopleClient.data("peerUid",peer,"text",value,"requestId",pending[0])).addOnSuccessListener(t->{dialog.dismiss();say("Stored for "+who+". They may be offline; an opened receipt appears after they read it in Milo.");}).addOnFailureListener(e->{say(PeopleClient.error(e));dialog.getButton(-1).setEnabled(true);});}).show();}));dialog.show();}
    void speechResult(Intent data){if(dictationTarget==null||data==null)return;ArrayList<String> words=data.getStringArrayListExtra(RecognizerIntent.EXTRA_RESULTS);if(words!=null&&!words.isEmpty())dictationTarget.setText(words.get(0));}
    void openMessage(DocumentSnapshot m){FirebaseUser u=PeopleClient.current();if(u==null)return;boolean received=u.getUid().equals(m.getString("toUid"));String peer=received?m.getString("fromUid"):m.getString("toUid"),who=people.containsKey(peer)?label(people.get(peer)):m.getString("fromName");LinearLayout f=form();f.addView(a.text(m.getString("fromName")+" · "+m.getString("fromEmail"),12));TextView message=a.text(m.getString("text"),17);message.setTextIsSelectable(true);f.addView(message);if(received){action(f,"Read aloud",()->{if(!a.prefs.getBoolean("pet_enabled",true)){say("Enable Milo in Setup for speech.");return;}if(!a.voiceReady){say("No spoken voice is ready. Use Setup → Test speaker.");return;}a.speech.stop();a.speech.speak(who+" says: "+m.getString("text"),null,"milo-test-people");});action(f,"Reply",()->{a.speech.stop();compose(peer,who,"");});}
        action(f,"Delete my copy",()->new AlertDialog.Builder(a).setTitle("Delete this message copy?").setMessage("This removes your copy. The other person's copy is not removed.").setNegativeButton("Keep",null).setPositiveButton("Delete",(x,w)->PeopleClient.call("deleteMessage",PeopleClient.data("messageId",m.getId())).addOnSuccessListener(t->say("Your copy was removed.")).addOnFailureListener(e->say(PeopleClient.error(e)))).show());AlertDialog shown=new AlertDialog.Builder(a).setTitle(received?"Message from "+who:"Your sent message").setView(f).setPositiveButton("Close",null).create();shown.setOnDismissListener(d->{if(a.speech!=null)a.speech.stop();});shown.show();if(received)PeopleClient.call("markRead",PeopleClient.data("messageId",m.getId())).addOnFailureListener(e->say("Read receipt could not sync yet."));}
    boolean sameAccount(String uid){FirebaseUser current=PeopleClient.current();return current!=null&&uid.equals(current.getUid());}
    void notificationFailure(String message){a.prefs.edit().putBoolean("people_notifications",false).remove("people_notifications_owner").apply();FirebaseMessaging.getInstance().setAutoInitEnabled(false);if(live()&&notificationSwitch!=null)notificationSwitch.setChecked(false);say(message);}
    void enableNotifications(){if(!signedIn())return;String uid=PeopleClient.current().getUid();int turn=++notificationRequest;FirebaseMessaging.getInstance().getToken().addOnSuccessListener(token->{if(!sameAccount(uid)||turn!=notificationRequest)return;PeopleClient.call("registerDevice",PeopleClient.data("token",token,"ownerUid",uid)).addOnSuccessListener(t->{if(!sameAccount(uid)||turn!=notificationRequest)return;a.prefs.edit().putBoolean("people_notifications",true).putString("people_notifications_owner",uid).apply();FirebaseMessaging.getInstance().setAutoInitEnabled(true);if(live()&&notificationSwitch!=null)notificationSwitch.setChecked(true);say("Message notifications enabled. Your inbox remains available when notifications are off.");}).addOnFailureListener(e->{if(sameAccount(uid)&&turn==notificationRequest)notificationFailure(PeopleClient.error(e));});}).addOnFailureListener(e->{if(sameAccount(uid)&&turn==notificationRequest)notificationFailure("Could not register this phone for notifications.");});}
    void disableNotifications(){notificationRequest++;boolean was=a.prefs.getBoolean("people_notifications",false);String owner=a.prefs.getString("people_notifications_owner","");a.prefs.edit().putBoolean("people_notifications",false).remove("people_notifications_owner").apply();if(was&&PeopleClient.ready(a)&&sameAccount(owner))FirebaseMessaging.getInstance().getToken().addOnSuccessListener(token->{if(sameAccount(owner))PeopleClient.call("unregisterDevice",PeopleClient.data("token",token));});FirebaseMessaging.getInstance().setAutoInitEnabled(false);}
    void signOut(){PeopleClient.signOut(a);refresh();}
}
